import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 8;

const SCENE_HERO = 70;
const SCENE_BENEFITS = 80;
const SCENE_SIGNOFF = 70;

export const durationInFrames =
  SCENE_HERO + SCENE_BENEFITS + SCENE_SIGNOFF - TRANSITION * 2;

// ---------- Background ----------
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
    {/* Subtle radial vignette for depth */}
    <AbsoluteFill
      style={{
        background: `radial-gradient(120% 80% at 20% 30%, rgba(248,102,6,0.06), transparent 60%)`,
      }}
    />
  </AbsoluteFill>
);

// ---------- Scene 1: Hero ----------
const HeroScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const introIn = springIn(frame, vfps, 10, "SNAPPY");
  const v3In = springIn(frame, vfps, 22, "LIQUID");
  const highlightIn = springIn(frame, vfps, 30, "LIQUID");
  const ruleIn = springIn(frame, vfps, 40, "GENTLE");

  const driftY = ambientDrift(frame, 2.5, 90, "hero-title");
  const driftX = ambientDrift(frame, 1.5, 110, "hero-x");

  const eyebrowStyle = {
    opacity: eyebrowIn,
    transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px)`,
  };

  const introStyle = compoundReveal(frame, vfps, {
    delay: 10,
    preset: "SNAPPY",
    translateY: 50,
    scaleFrom: 0.94,
    blurFrom: 10,
  });

  const v3Style = compoundReveal(frame, vfps, {
    delay: 22,
    preset: "LIQUID",
    translateY: 60,
    scaleFrom: 0.9,
    blurFrom: 12,
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
      <Background />

      {/* Off-center hero anchored left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "26%",
          maxWidth: "84%",
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            ...eyebrowStyle,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 28,
            fontWeight: 600,
            color: COLORS.orange,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            marginBottom: 28,
          }}
        >
          Product Announcement · 2025
        </div>

        {/* "Introducing" */}
        <div
          style={{
            ...introStyle,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 132,
            fontWeight: 600,
            color: COLORS.text,
            letterSpacing: "-0.035em",
            lineHeight: 0.95,
          }}
        >
          Introducing
        </div>

        {/* "Actors v3" with highlighted v3 */}
        <div
          style={{
            ...v3Style,
            marginTop: 12,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 196,
            fontWeight: 600,
            color: COLORS.text,
            letterSpacing: "-0.045em",
            lineHeight: 0.92,
            display: "flex",
            alignItems: "baseline",
            gap: 28,
          }}
        >
          <span>Actors</span>
          <span
            style={{
              position: "relative",
              display: "inline-block",
              color: COLORS.text,
              background: COLORS.orangeTint,
              borderBottom: `5px solid ${COLORS.orange}`,
              padding: "0 22px",
              borderRadius: 12,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            v3
          </span>
        </div>

        {/* Thin accent rule */}
        <div
          style={{
            marginTop: 56,
            width: interpolate(ruleIn, [0, 1], [0, 220]),
            height: 3,
            backgroundColor: COLORS.orange,
            opacity: ruleIn,
            borderRadius: 2,
          }}
        />
      </div>

      {/* Bottom-left metadata caption */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          bottom: "10%",
          fontFamily: "monospace",
          fontSize: 22,
          color: COLORS.textSubtle,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          opacity: ruleIn,
        }}
      >
        v3.0 / shipping now
      </div>
    </AbsoluteFill>
  );
};

// ---------- Scene 2: Benefits ----------
const BENEFITS = [
  {
    label: "Faster cold starts",
    descriptor: "Sub-second boot on every Actor run",
  },
  {
    label: "Native MCP support",
    descriptor: "Plug directly into any AI agent stack",
  },
  {
    label: "Pay per second",
    descriptor: "Only billed for the compute you actually use",
  },
];

const CheckGlyph: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <circle
      cx={12}
      cy={12}
      r={11}
      fill="none"
      stroke={COLORS.orange}
      strokeWidth={1.5}
      opacity={progress * 0.6}
    />
    <path
      d="M6 12.5 L10.5 17 L18 7.5"
      stroke={COLORS.orange}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={26}
      strokeDashoffset={interpolate(progress, [0, 1], [26, 0])}
    />
  </svg>
);

const BenefitsScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width } = useVideoConfig();

  const headlineIn = springIn(frame, vfps, 4, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 14, "LIQUID");

  const headlineStyle = compoundReveal(frame, vfps, {
    delay: 4,
    preset: "SNAPPY",
    translateY: 36,
    scaleFrom: 0.94,
    blurFrom: 8,
  });

  const headlineDrift = ambientDrift(frame, 2, 100, "ben-headline");

  return (
    <AbsoluteFill style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
      <Background />

      {/* Asymmetric grid: headline left, benefits right-ish */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "14%",
          maxWidth: "84%",
        }}
      >
        <div
          style={{
            ...headlineStyle,
            transform: `${headlineStyle.transform} translateY(${headlineDrift}px)`,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 96,
            fontWeight: 600,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.02,
            maxWidth: "70%",
          }}
        >
          Rebuilt for{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `4px solid ${COLORS.orange}`,
              padding: "0 14px",
              borderRadius: 8,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            speed
          </span>
          .
        </div>
      </div>

      {/* Benefit rows in a card, anchored lower-left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          bottom: "10%",
          width: "62%",
          backgroundColor: "rgba(255,255,255,0.04)",
          border: `1px solid ${COLORS.border}`,
          borderRadius: 18,
          padding: "44px 48px",
          display: "flex",
          flexDirection: "column",
          gap: 32,
          backdropFilter: "blur(20px)",
        }}
      >
        {BENEFITS.map((b, i) => {
          const p = staggeredSpring(
            frame,
            vfps,
            i,
            28,
            TIMING.staggerItem,
            "GENTLE",
          );
          const drift = ambientDrift(frame, 1.2, 120 + i * 10, `ben-${i}`);
          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 28,
                opacity: p,
                transform: `translateX(${interpolate(p, [0, 1], [-30, 0])}px) translateY(${drift}px)`,
              }}
            >
              <CheckGlyph size={52} progress={p} />
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                }}
              >
                <div
                  style={{
                    fontFamily: "'GT Walsheim', Inter, sans-serif",
                    fontSize: 52,
                    fontWeight: 600,
                    color: COLORS.text,
                    letterSpacing: "-0.015em",
                    lineHeight: 1.05,
                  }}
                >
                  {b.label}
                </div>
                <div
                  style={{
                    fontFamily: "Inter, sans-serif",
                    fontSize: 26,
                    fontWeight: 400,
                    color: COLORS.textMuted,
                    letterSpacing: "-0.005em",
                  }}
                >
                  {b.descriptor}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Right-side index pill */}
      <div
        style={{
          position: "absolute",
          right: "8%",
          top: "16%",
          fontFamily: "monospace",
          fontSize: 22,
          color: COLORS.textSubtle,
          letterSpacing: "0.2em",
          textTransform: "uppercase",
          opacity: headlineIn,
        }}
      >
        02 / what's new
      </div>
    </AbsoluteFill>
  );
};

// ---------- Scene 3: Sign-off ----------
const SignoffScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  const buildIn = springIn(frame, vfps, 4, "SNAPPY");
  const runIn = springIn(frame, vfps, 14, "SNAPPY");
  const scaleIn = springIn(frame, vfps, 24, "SNAPPY");
  const captionIn = springIn(frame, vfps, 38, "GENTLE");
  const ctaIn = springIn(frame, vfps, 46, "LIQUID");

  const breathe = 1 + Math.sin(frame / 28) * 0.012;
  const driftY = ambientDrift(frame, 2, 100, "signoff");

  const wordStyle = (p: number) => ({
    opacity: p,
    display: "inline-block",
    transform: `translateY(${interpolate(p, [0, 1], [40, 0])}px) scale(${interpolate(p, [0, 1], [0.92, 1])})`,
    filter: `blur(${interpolate(p, [0, 1], [8, 0])}px)`,
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
      <Background />

      {/* Hero tagline anchored left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "30%",
          maxWidth: "88%",
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 168,
            fontWeight: 500,
            color: COLORS.text,
            letterSpacing: "-0.045em",
            lineHeight: 0.95,
            display: "flex",
            flexWrap: "wrap",
            gap: 32,
          }}
        >
          <span style={wordStyle(buildIn)}>Build.</span>
          <span style={wordStyle(runIn)}>Run.</span>
          <span
            style={{
              ...wordStyle(scaleIn),
              color: COLORS.orange,
            }}
          >
            Scale.
          </span>
        </div>

        {/* Accent rule */}
        <div
          style={{
            marginTop: 44,
            width: interpolate(captionIn, [0, 1], [0, 280]),
            height: 3,
            backgroundColor: COLORS.orange,
            opacity: captionIn,
            borderRadius: 2,
          }}
        />

        <div
          style={{
            marginTop: 28,
            fontFamily: "Inter, sans-serif",
            fontSize: 32,
            fontWeight: 400,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            opacity: captionIn,
            transform: `translateY(${interpolate(captionIn, [0, 1], [12, 0])}px)`,
          }}
        >
          Actors v3 is live on apify.com
        </div>
      </div>

      {/* CTA pill bottom-left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          bottom: "12%",
          opacity: ctaIn,
          transform: `translateY(${interpolate(ctaIn, [0, 1], [16, 0])}px) scale(${breathe})`,
        }}
      >
        <div
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 14,
            border: `1.5px solid ${COLORS.orange}`,
            borderRadius: 999,
            padding: "16px 32px",
            color: COLORS.orange,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 600,
            fontSize: 28,
            letterSpacing: "-0.005em",
          }}
        >
          Try Actors v3 →
        </div>
      </div>

      {/* Bottom-right metadata */}
      <div
        style={{
          position: "absolute",
          right: "8%",
          bottom: "12%",
          fontFamily: "monospace",
          fontSize: 22,
          color: COLORS.textSubtle,
          letterSpacing: "0.2em",
          textTransform: "uppercase",
          opacity: ctaIn,
        }}
      >
        apify.com / v3
      </div>
    </AbsoluteFill>
  );
};

// ---------- Main Composition ----------
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_HERO + TRANSITION}>
        <HeroScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={SCENE_BENEFITS + TRANSITION}>
        <BenefitsScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={SCENE_SIGNOFF}>
        <SignoffScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
